export function readApiToken(user: { role: string }): string {
  if (user.role !== 'admin') throw new Error('forbidden');
  return process.env.API_TOKEN ?? '';
}

type Lease = { expiresAt: string };
export function expired(lease: Lease): boolean {
  return Date.now() > (lease.expiresAt as unknown as number);
}

type Lease = { expiresAt: string };
export function expired(lease: Lease): boolean {
  const timestamp = Date.parse(lease.expiresAt);
  if (!Number.isFinite(timestamp)) throw new Error('invalid expiry');
  return Date.now() > timestamp;
}

interface Store { read(): Promise<number>; write(value: number): Promise<void> }
export async function add(store: Store, amount: number): Promise<void> {
  const current = await store.read();
  await store.write(current + amount);
}

interface Store { addAtomic(amount: number): Promise<void> }
export async function add(store: Store, amount: number): Promise<void> {
  await store.addAtomic(amount);
}

export async function charge(body: string): Promise<Response> {
  for (let attempt = 0; attempt < 3; attempt += 1) {
    try { return await fetch('/charge', { method: 'POST', body }); } catch {}
  }
  throw new Error('charge failed');
}

export async function charge(body: string, key: string): Promise<Response> {
  return fetch('/charge', { method: 'POST', body, headers: { 'idempotency-key': key } });
}

interface Store { markDone(id: string): Promise<void>; writeResult(id: string, value: string): Promise<void> }
export async function finish(store: Store, id: string, value: string): Promise<void> {
  await store.markDone(id);
  await store.writeResult(id, value);
}

interface Store { writeResult(id: string, value: string): Promise<void>; markDone(id: string): Promise<void> }
export async function finish(store: Store, id: string, value: string): Promise<void> {
  await store.writeResult(id, value);
  await store.markDone(id);
}

interface Store { clear(): Promise<void>; restore(data: string): Promise<void> }
export async function restore(store: Store, backup: string): Promise<void> {
  await store.clear();
  JSON.parse(backup);
  await store.restore(backup);
}

interface Store { replaceAtomically(data: string): Promise<void> }
export async function restore(store: Store, backup: string): Promise<void> {
  JSON.parse(backup);
  await store.replaceAtomically(backup);
}
